fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Since tol is strictly positive, we check if the difference is strictly within (-tol, tol).
    // This is equivalent to abs(a - b) < tol.
    // Careful: diff (a - b) may overflow if we did direct subtraction,
    // but i8 subtraction wraps. Here subtraction is safe because range fits.
    // We just cast to i16 to avoid overflow in absolute difference calculation.
    let diff = (a as i16) - (b as i16);
    diff.abs() < (tol as i16)
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Assumptions: a.len() == b.len() > 0 and tol > 0
    let len = a.len();
    // allocate output vector with the same length
    let mut result = Vec::with_capacity(len);

    for i in 0..len {
        // Use the scalar is_close_i8 to determine the boolean value for each index
        result.push(is_close_i8(a[i], b[i], tol));
    }

    result
}

